-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "itIT" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.hunter.ranged.Name"] = "A distanza"
L["rm.era.hunter.ranged.Description"] = "Ogni Cacciatore dal livello 1 al 60, tutti gli alberi dei talenti. Ingaggia con Marchio del Cacciatore, Tiro Mirato e Tiro Automatico. Da solo, il famiglio fa da difensore: il tuo Morso del Serpente, poi Tiro Mirato, Tiro Arcano e Tiro Multiplo solo finché il mana è sopra la metà, Tiro Stordente per il kiting prima di avere un famiglio. In gruppo, Tiro Mirato e Tiro Multiplo subito dopo un Tiro Automatico, così che non venga mai ritardato, Morso del Serpente fuori dalle incursioni, Tiro Arcano solo prima di Tiro Mirato o su un bersaglio in punto di morte. Pulsanti da mischia quando un nemico è troppo vicino, incantesimi istantanei in movimento, Tiro Multiplo e Raffica contro tre o più nemici. Promemoria: Falco (prima di averlo, Scimmia), Aura di Precisione, cura del famiglio, Rapidità di Tiro, Ira Bestiale e abilità razziali sulle élite e nelle istanze, Intimidazione e Morte Apparente. Trappole, Laccio, Nutri Famiglio, Tiro Tranquillizzante e posizionamento restano a te."
L["rm.era.hunter.ranged.icyveins.Name"] = "A distanza, con clipping (Icy Veins)"
L["rm.era.hunter.ranged.icyveins.Description"] = "Disattivata per impostazione predefinita; attivala per un'arma a distanza più veloce di 3,0 secondi. Come Cacciatore: a distanza, ma in gruppo Tiro Mirato e Tiro Multiplo partono appena sono pronti, anche se ritardano un Tiro Automatico, Morso del Serpente non viene mai usato, e Rapidità di Tiro, Ira Bestiale e le abilità razziali vengono usate a ogni ingaggio."
L["rm.era.hunter.ranged.simulator.Name"] = "A distanza, Morso del Serpente in incursione (simulatore)"
L["rm.era.hunter.ranged.simulator.Description"] = "Disattivata per impostazione predefinita; attivala dove l'incursione ha spazio tra le penalità per il tuo morso. Come Cacciatore: a distanza, ma in gruppo Morso del Serpente viene mantenuto ovunque, incursioni comprese, e rinnovato sotto i 5 secondi mentre Tiro Mirato e Tiro Multiplo sono entrambi in tempo di recupero, e Tiro Arcano non viene mai usato."
L["rm.forever.hunter.ranged.Name"] = "A distanza (Wowhead)"
L["rm.forever.hunter.ranged.Description"] = "Ogni Cacciatore a distanza dal livello 1 al 60 (Affinità Animale, Precisione di Tiro e Sopravvivenza fino a Calcio del Trampoliere), e la scelta predefinita del Cacciatore di Forever. Ingaggio: Marchio del Cacciatore, Tiro da Cecchino finché dura Uccisione Rapida, Tiro Automatico. Poi il tuo Morso della Serpe, Evocazione: Falco due volte e Tiro Arcano una volta durante il loro tempo di recupero condiviso (Tiro Arcano appena pronto prima di Evocazione: Falco), Tiro da Cecchino con Uccisione Rapida o sulle élite, Tiro Mirato. Due o più nemici che ti combattono: Tiro Multiplo invece di Tiro Mirato, Trappola Esplosiva con tre vicino a te, Raffica con cinque. In movimento: solo tiri istantanei. Un mostro a portata di mischia riceve Assalto del Rapace e Morso della Mangusta. Promemoria: Aspetto del Falco (Scimmia prima di averlo), Aura del Tiro Preciso, richiamo e rianimazione del famiglio, Fuoco Rapido, Ira Bestiale e Furia Sanguinaria sulle élite o nelle spedizioni, Intimidazione quando un mostro ti attacca. Comandi del famiglio, nutrimento, kiting e Morte Apparente restano a te; disattiva i promemoria del famiglio se giochi Lupo Solitario. Non legge mai il tuo mana né la salute di nessuno, che Forever nasconde agli addon, quindi Marchio del Cacciatore e Morso della Serpe vanno su ogni bersaglio e Cura Famiglio spetta a te."
L["rm.forever.hunter.ranged.mobalytics.Name"] = "A distanza, risparmio di mana (Mobalytics)"
L["rm.forever.hunter.ranged.mobalytics.Description"] = "Lo stile di livellamento a risparmio di mana di Mobalytics, un'alternativa alla rotazione integrata consigliata a distanza di Wowhead, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità. Mantiene il tuo Morso della Serpe, un Falco evocato, Tiro Mirato (Tiro Multiplo contro due o più nemici), e mai Tiro Arcano una volta conosciuto Evocazione: Falco; il secondo Falco su un bersaglio in salute è escluso, perché Forever nasconde la salute del bersaglio. Stesso ingaggio, mischia, movimento e promemoria della rotazione integrata di Wowhead."
L["rm.forever.hunter.survival.Name"] = "Sopravvivenza in mischia (Wowhead)"
L["rm.forever.hunter.survival.Description"] = "Sopravvivenza in mischia con due armi una volta che Sopravvivenza è il tuo albero dei talenti principale con 21 punti, il livello di Calcio del Trampoliere (fino ad allora ti fa livellare la rotazione integrata a distanza, come consigliano le guide). Ingaggia con Marchio del Cacciatore e Morso della Serpe, poi Morso della Mangusta, Calcio del Trampoliere, Assalto del Rapace e Contrattacco, con Trappola Esplosiva contro tre o più nemici. Fuori dalla mischia tira: Morso della Serpe, Tiro Arcano, Tiro Mirato, Tiro Automatico. Promemoria: Aspetto della Bestia, Marchio del Cacciatore (Esponi Preda ne ha bisogno), Fuoco Rapido e Furia Sanguinaria sulle élite o nelle spedizioni, Prevenzione finché tieni l'attenzione del bersaglio, cura del famiglio (su Forever la salute è nascosta, quindi Cura Famiglio spetta a te). Un passaggio facoltativo con Trappola d'Immolazione è disattivato per impostazione predefinita."
L["rm.forever.hunter.survival.weave.Name"] = "Sopravvivenza, alternanza con arma a due mani (Wowhead)"
L["rm.forever.hunter.survival.weave.Description"] = "L'alternanza dentro e fuori dalla mischia di Wowhead per un Cacciatore Sopravvivenza con arma a due mani, un'alternativa alla rotazione integrata consigliata Sopravvivenza in mischia, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità. In mischia: Morso della Mangusta e Assalto del Rapace; quando mancano più di 2,5 secondi ad Assalto del Rapace, Calcio del Trampoliere e allontanati. Fuori dalla mischia: Morso della Serpe, Tiro Arcano, Tiro Mirato e Tiro Automatico finché Assalto del Rapace è quasi pronto, poi di nuovo dentro. I movimenti li fai tu; RM segue la tua distanza."
L["rm.mop.hunter.beastmastery.Name"] = "Consigliata"
L["rm.mop.hunter.beastmastery.Description"] = "Scelta automaticamente nella specializzazione Affinità Animale. Apre con Marchio del Cacciatore e Ordine di Morte, poi: Tiro Mortale, Ordine di Morte (trattenuto per un momento quando Ira Bestiale sta per essere pronta), Stormo di Corvi, Scatto della Lince, Bestia Feroce e il tiro del talento di sesto livello se lo hai scelto, Focalizzazione a cinque cumuli di Frenesia (o a quattro che stanno per svanire) ma non durante Ira Bestiale, Morso del Serpente sui bersagli che sopravvivranno, Tiro del Cobra per rinnovarlo, Tiro Arcano a 80 di focus o durante Ira Bestiale, poi Tiro del Cobra (Tiro Stabilizzato prima del livello 81). Con due o più nemici che ti combattono mantiene attivo Fendente Bestiale con Tiro Multiplo, conserva Ordine di Morte per il focus in avanzo sui grandi gruppi e suggerisce Trappola Esplosiva da tre. Promemoria: famiglio evocato, rianimato e curato, Aspetto del Falco o del Falco di Ferro, Tiro di Contrasto, Zelo, e Ira Bestiale, Rapidità di Tiro, Impeto e abilità razziali quando il combattimento ne vale la pena (un'élite, una spedizione o un'incursione, o un bersaglio che sopravvivrà). Posizionamento delle trappole, Depistaggio, Morte Apparente e abilità difensive restano a te; i promemoria di Fuga Curativa e Prevenzione sono disattivati per impostazione predefinita."
L["rm.mop.hunter.marksmanship.Name"] = "Consigliata"
L["rm.mop.hunter.marksmanship.Description"] = "Scelta automaticamente nella specializzazione Precisione di Tiro. Prelancia Tiro Mirato, poi: Tiri Stabilizzati a coppie per mantenere attivo Focus Stabilizzato (dal livello 63), Tiro della Chimera, Morso del Serpente sui bersagli che sopravvivranno, Tiro Mirato ogni volta che Fuoco! lo rende istantaneo, Tiro Mortale, i tuoi talenti, e un Tiro Mirato lanciato normalmente mentre il bersaglio è sopra l'80% di salute, durante Rapidità di Tiro o Brama di Sangue, a 85 di focus o quando Tiro della Chimera è a pochi secondi. Tiro Arcano solo mentre ti muovi; altrimenti Tiro Stabilizzato. Quattro o più nemici: Tiro della Chimera, Tiro Mirato istantaneo, Tiro Multiplo, Tiro Mortale, Trappola Esplosiva. Stessi promemoria delle altre rotazioni integrate del Cacciatore. Se preferisci spendere il focus in avanzo in Tiro Arcano, usa la variante con Tiro Arcano."
L["rm.mop.hunter.marksmanship.icyveins.Name"] = "Focus in eccesso su Tiro Arcano (Icy Veins)"
L["rm.mop.hunter.marksmanship.icyveins.Description"] = "Un'alternativa alla rotazione integrata Precisione di Tiro, come la giocano Icy Veins, Method, wowtbc.gg e Hekili: Tiro Mirato viene lanciato normalmente solo con il bersaglio sopra l'80% di salute o durante Rapidità di Tiro o Brama di Sangue, e il focus in avanzo va invece a Tiro Arcano a 60. Focus Stabilizzato viene rinnovato sotto i 4 secondi; contro quattro o più nemici Tiro Multiplo viene per primo. Disattivata per impostazione predefinita: attivala e disattiva la rotazione integrata Precisione di Tiro, oppure alzane la priorità."
L["rm.mop.hunter.survival.Name"] = "Consigliata"
L["rm.mop.hunter.survival.Description"] = "Scelta automaticamente nella specializzazione Sopravvivenza. Apre con Marchio del Cacciatore, Freccia Nera e Tiro Esplosivo, poi: Tiro Esplosivo appena pronto e a ogni Pronto al Tiro, Tiro Mortale, Freccia Nera sui bersagli che sopravvivranno, i tuoi talenti, Morso del Serpente mantenuto da Tiro del Cobra, Tiro Arcano a 75 di focus, con Brivido della Caccia, o a 55 quando Freccia Nera non sta per tornare disponibile, poi Tiro del Cobra (Tiro Stabilizzato prima del livello 81). Due o più nemici: prima Tiro Multiplo con Pronto al Tiro e focus pieno, Tiro Esplosivo fino a cinque bersagli, Tiro Mortale, Freccia Nera, Trappola Esplosiva da tre, Tiro Multiplo per spendere. Stessi promemoria delle altre rotazioni integrate del Cacciatore; le trappole per i proc di Pronto al Tiro restano a te."
L["rm.mop.hunter.unspecialized.Name"] = "Prima di una specializzazione"
L["rm.mop.hunter.unspecialized.Description"] = "Per i livelli da 1 a 9 e qualsiasi Cacciatore che non ha scelto una specializzazione; le rotazioni integrate Affinità Animale, Precisione di Tiro e Sopravvivenza subentrano appena scegli una specializzazione. Ingaggia con Marchio del Cacciatore e Tiro Arcano, poi Morso del Serpente sui bersagli che sopravvivranno, Tiro Multiplo contro tre o più nemici, Tiro Arcano, Tiro Stabilizzato e Tiro Automatico. Ti ricorda di richiamare, rianimare e curare il tuo famiglio e di mantenere attivo Aspetto del Falco."
L["rm.retail.hunter.beastmastery.Name"] = "Assistente di Combattimento di Blizzard"
L["rm.retail.hunter.beastmastery.Description"] = "Consigliata per Affinità Animale. Evidenzia il prossimo incantesimo suggerito dall'Assistente di Combattimento di Blizzard, l'unico consiglio di rotazione che il gioco permette ancora a un addon di leggere in combattimento in Midnight (richiama da sé il tuo famiglio); attende mentre lanci o incanali. Al suo fianco, promemoria per ciò che l'Assistente di Combattimento lascia a te: Carneficina e il tuo tempo di recupero razziale in combattimento, Tiro di Contrasto su un lancio interrompibile, e Legge del Più Forte ogni volta che è pronta in combattimento. I lanci nemici sono nascosti in combattimento, quindi l'interruzione si illumina solo dove il gioco li mostra; la salute è nascosta su Retail, quindi decidi tu quando usare le tue difese (Fuga Curativa e Aspetto della Tartaruga compresi). I monili, Depistaggio e la cura del famiglio restano a te."
L["rm.retail.hunter.beastmastery.guide.Name"] = "Riferimento (SimulationCraft e Icy Veins)"
L["rm.retail.hunter.beastmastery.guide.Description"] = "Solo riferimento, disattivata per impostazione predefinita: la priorità ottimizzata di Affinità Animale. Cariche, tempi di recupero e proc sono nascosti agli addon in combattimento in Midnight, quindi lì non può funzionare; leggila o duplicala per sperimentare. Il Focus è nascosto su Retail. Richiama il tuo famiglio e applica Marchio del Cacciatore al bersaglio prima dell'ingaggio. Tiro Lacerante subito prima di Ira Bestiale o prima che raggiunga il massimo di cariche; Ira Bestiale; Ordine di Morte con Ululato del Capobranco o Alleanza con la Natura, o liberamente quando Ira Bestiale è lontana; Tiro del Cobra con Zanna del Cobra; Tiro del Cobra; Tiro Lacerante quando non hai abbastanza Focus per Tiro del Cobra. Guardaboschi Oscuro: Freccia Nera durante Fuoco Indebolente e Freccia Funesta quando finisce. Contro tre o più nemici (due con Fendente Bestiale): Falciata Selvaggia per avviare Fendente Bestiale, poi Ordine di Morte, Tiro Lacerante e Tiro del Cobra finché dura. Promemoria: Carneficina e i promemoria di utilità della rotazione integrata dell'Assistente di Combattimento."
L["rm.retail.hunter.initial.Name"] = "Assistente di Combattimento di Blizzard"
L["rm.retail.hunter.initial.Description"] = "Consigliata prima di scegliere una specializzazione (mentre il gioco segnala la specializzazione iniziale del Cacciatore). Evidenzia il prossimo incantesimo suggerito dall'Assistente di Combattimento di Blizzard, l'unico consiglio di rotazione che il gioco permette ancora a un addon di leggere in combattimento in Midnight; attende mentre lanci o incanali. Al suo fianco, i promemoria che ogni rotazione integrata del Cacciatore condivide, ciascuno una volta che conosci il suo incantesimo. Quando scegli una specializzazione al livello 10, subentrano le rotazioni integrate di quella specializzazione."
L["rm.retail.hunter.marksmanship.Name"] = "Assistente di Combattimento di Blizzard"
L["rm.retail.hunter.marksmanship.Description"] = "Consigliata per Precisione di Tiro. Evidenzia il prossimo incantesimo suggerito dall'Assistente di Combattimento di Blizzard, l'unico consiglio di rotazione che il gioco permette ancora a un addon di leggere in combattimento in Midnight; attende mentre lanci o incanali. Al suo fianco, promemoria per ciò che l'Assistente di Combattimento lascia a te: Precisione e il tuo tempo di recupero razziale in combattimento, Tiro di Contrasto su un lancio interrompibile, e Legge del Più Forte ogni volta che è pronta in combattimento. I lanci nemici sono nascosti in combattimento, quindi l'interruzione si illumina solo dove il gioco li mostra; la salute è nascosta su Retail, quindi decidi tu quando usare le tue difese (Fuga Curativa e Aspetto della Tartaruga compresi)."
L["rm.retail.hunter.marksmanship.guide.Name"] = "Riferimento (SimulationCraft e Icy Veins)"
L["rm.retail.hunter.marksmanship.guide.Description"] = "Solo riferimento, disattivata per impostazione predefinita: la priorità ottimizzata di Precisione di Tiro, che spende Tiri Precisi prima del Tiro Mirato successivo. Proc e cariche sono nascosti in combattimento in Midnight, quindi lì non può funzionare; il Focus è nascosto su Retail, quindi il Tiro Multiplo a 70 di Focus contro i gruppi è escluso. Applica Marchio del Cacciatore al bersaglio e apre con Tiro Mirato. Sentinella: Tiro Esplosivo, Raffica, Precisione, Chakram della Luce Lunare prima che finisca la sua finestra, Tiro Mirato durante Precisione senza Tiri Precisi, Rapidità di Tiro, Tiro Mortale, Tiro Multiplo (due nemici con Aspetto dell'Idra) o Tiro Arcano con Tiri Precisi, Tiro Mirato, Chakram della Luce Lunare, Tiro Stabilizzato. Guardaboschi Oscuro: prima Freccia Nera con Tiri Precisi, niente Tiro Esplosivo durante Pronto al Tiro, Tiro Mirato prima che raggiunga il massimo di cariche, Freccia Funesta. Contro tre o più nemici con Tiri Ingannevoli: Tiro Esplosivo, Raffica, Tiro Multiplo per applicare Tiri Ingannevoli, Precisione, poi Rapidità di Tiro e Tiro Mirato finché dura. Usare Precisione per 30 cumuli di Centro o su un bersaglio senza marchio resta a te."
L["rm.retail.hunter.survival.Name"] = "Assistente di Combattimento di Blizzard"
L["rm.retail.hunter.survival.Description"] = "Consigliata per Sopravvivenza. Evidenzia il prossimo incantesimo suggerito dall'Assistente di Combattimento di Blizzard, l'unico consiglio di rotazione che il gioco permette ancora a un addon di leggere in combattimento in Midnight (richiama da sé il tuo famiglio); attende mentre lanci o incanali. Al suo fianco, promemoria per ciò che l'Assistente di Combattimento lascia a te: Abbattimento e il tuo tempo di recupero razziale in combattimento, Museruola su un lancio interrompibile, e Legge del Più Forte ogni volta che è pronta in combattimento. I lanci nemici sono nascosti in combattimento, quindi l'interruzione si illumina solo dove il gioco li mostra; la salute è nascosta su Retail, quindi decidi tu quando usare le tue difese (Fuga Curativa e Aspetto della Tartaruga compresi)."
L["rm.retail.hunter.survival.guide.Name"] = "Riferimento (SimulationCraft)"
L["rm.retail.hunter.survival.guide.Description"] = "Solo riferimento, disattivata per impostazione predefinita: la priorità Sopravvivenza di SimulationCraft, in cui Ordine di Morte genera Punta della Lancia e Abbattimento, Cannalunga, Bomba di Fuocobrado e Assalto del Raptor la spendono. Punta della Lancia e le cariche sono nascosti in combattimento in Midnight, quindi lì non può funzionare. Richiama il tuo famiglio, applica Marchio del Cacciatore al bersaglio e apre con Bomba di Fuocobrado. Sentinella: Ordine di Morte senza Punta della Lancia, Cannalunga, Bomba di Fuocobrado con Marchio della Sentinella, Ordine di Morte prima di un Abbattimento pronto, Abbattimento, Chakram della Luce Lunare, Assalto del Raptor, poi Ordine di Morte, Bomba di Fuocobrado e Abbattimento. Capobranco: Ordine di Morte con Ululato del Capobranco, poi Abbattimento, Bomba di Fuocobrado, Cannalunga e Assalto del Raptor con Punta della Lancia. Contro tre o più nemici: Cannalunga e Bomba di Fuocobrado prima di Abbattimento, Spazzata del Raptor. Promemoria: Aspetto dell'Aquila fuori dalla mischia e i promemoria di utilità."
L["rm.sod.hunter.melee.Name"] = "In mischia (SoD)"
L["rm.sod.hunter.melee.Description"] = "Scelta su un reame della Season of Discovery una volta che incidi Assalto Fiancheggiato, Assalto della Viverna o Scorticatura e né Tiro della Chimera né Tiro Esplosivo. Mantiene attivo l'effetto benefico di Assalto Fiancheggiato, Morso della Mangusta a quattro cumuli di Furia del Raptor, Assalto della Viverna con Colpi Astuti, Assalto del Raptor a ogni azzeramento, poi Morso della Mangusta, Assalto della Viverna, Assalto Fiancheggiato e Scorticatura; Trappola Incendiaria e Laccio solo nei momenti vuoti. Scorticatura e Trappola Esplosiva contro tre o più nemici; Morso del Serpente e tiri mentre non puoi raggiungere il bersaglio. Promemoria: Aspetto del Falcone (Falco prima del 60), Vipera sotto il 5% di mana, cura del famiglio (nessuna con Lupo Solitario inciso), Rapidità di Tiro e abilità razziali una volta accumulato Assalto Fiancheggiato, Ira Bestiale. Posizionamento e comandi del famiglio restano a te."
L["rm.sod.hunter.ranged.Name"] = "A distanza (SoD)"
L["rm.sod.hunter.ranged.Description"] = "Ogni Cacciatore a distanza su un reame della Season of Discovery, dal livello 1 al 60; le rune vengono usate una volta incise. Morso del Serpente sempre attivo e rinnovato da Tiro della Chimera. Con la runa per le gambe Tiro Mortale: Tiro Multiplo a quattro Tiri Ingannevoli, Tiro Mortale durante Rapidità di Tiro e sui bersagli in fase di esecuzione, Tiro della Chimera, poi Trappola Esplosiva e Tiro Arcano mentre Tiro Multiplo è in tempo di recupero. Senza di essa: Tiro della Chimera, Tiro Mirato a due cumuli di Addestramento da Cecchino (senza quella runa, subito dopo un Tiro Automatico), trappole appena prima che Tiro della Chimera sia pronto (Trappola Gelida solo per alimentare Pronto al Tiro), Tiro Esplosivo, Tiro Stabilizzato, Tiro Multiplo, Tiro Arcano. Pulsanti da mischia quando un nemico è troppo vicino, incantesimi istantanei in movimento, trappole, Tiro Multiplo e Raffica contro tre o più nemici. Promemoria: Falco, Vipera sotto il 10% di mana, Cuore del Leone, Aura di Precisione, cura del famiglio (nessuna con Lupo Solitario inciso), Focalizzazione a cinque cumuli di Frenesia, Rapidità di Tiro, abilità razziali e Ira Bestiale sulle élite e nelle istanze. Con Pronto al Tiro inciso, una Trappola Gelida prima dell'ingaggio. L'alternanza con la mischia e il posizionamento restano a te."
L["rm.tbc.hunter.ranged.simulator.Name"] = "DPS a distanza (simulatore)"
L["rm.tbc.hunter.ranged.simulator.Description"] = "Livelli 1–70, ogni specializzazione. Ingaggia con Marchio del Cacciatore, Tiro Mirato e Tiro Automatico, mantiene attivo il Tiro Automatico e usa gli attacchi in mischia quando un bersaglio ti raggiunge. Prima di Tiro Fermo mantiene il tuo Morso della Serpe e spende mana in Tiro Mirato, Tiro Multiplo e Tiro Arcano solo finché ne hai in abbondanza. Dal livello 62: Tiro Multiplo appena pronto, Tiro Fermo subito dopo ogni Tiro Automatico, Tiro Arcano per riempire i vuoti, Morso della Serpe quando giochi da solo. Con tre o più nemici che ti combattono, Tiro Multiplo ogni volta che è pronto. Ti ricorda gli aspetti (Vipera quando il mana scarseggia, di nuovo Falco a metà mana), la cura del famiglio, Ordine di Morte, i principali tempi di recupero su élite e boss e Tiro Silenziante. Comandi del famiglio, Depistaggio, trappole, Raffica, alternanza con la mischia e Morte Apparente restano a te."
L["rm.tbc.hunter.ranged.wowhead.Name"] = "DPS a distanza (Wowhead)"
L["rm.tbc.hunter.ranged.wowhead.Description"] = "Livelli 1–70, ogni specializzazione, seguendo i consigli di Wowhead per le incursioni. Stesso ingaggio, mischia, tiri da livellamento, Tiro Multiplo contro più bersagli e promemoria della versione simulatore, ma una volta appreso Tiro Fermo propone solo Tiro Multiplo e Tiro Fermo dopo ogni Tiro Automatico: niente Tiro Arcano come riempitivo (tranne in movimento), niente Morso della Serpe e niente promemoria di Aspetto della Vipera. Comandi del famiglio, Depistaggio, trappole, Raffica, alternanza con la mischia e Morte Apparente restano a te. Un'alternativa alla rotazione integrata consigliata a distanza di simulatore, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità."
